import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Tcard","description":"","frontmatter":{},"headers":[],"relativePath":"components/tcard.md","filePath":"components/tcard.md"}'),r={name:"components/tcard.md"};function c(n,e,i,s,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="tcard" tabindex="-1">Tcard <a class="header-anchor" href="#tcard" aria-label="Permalink to &quot;Tcard&quot;">​</a></h1><p>Tcard is one row of a table folded into a card, for a narrow screen.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it where a <a href="./table">Table</a> is too wide: one card for each row, with the names of the columns and the values as pairs of <code>dt</code> and <code>dd</code>. Controls do not go in a value; the row&#39;s actions go in <code>foot</code>. A card that is pressed takes <code>role</code>, <code>tabindex</code> and <code>onclick</code>. Inside <a href="./tcards">Tcards</a> it is placed at <code>y</code>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>sel</code></td><td><code>false</code></td><td>Selected</td></tr><tr><td><code>y</code></td><td></td><td>The distance from the top of Tcards, in px</td></tr><tr><td><code>foot</code></td><td></td><td>The row&#39;s actions, at the bottom right</td></tr><tr><td><code>children</code></td><td>required</td><td>Pairs of <code>dt</code> and <code>dd</code></td></tr></tbody></table><p>Other attributes (<code>role</code>, <code>tabindex</code>, <code>aria-*</code>, <code>data-*</code>) go to the element.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A line around it and pad-md inside. The names (6rem wide, muted) and the values sit in two columns, gap-md apart, with gap-sm between the rows; both are trimmed to their ink, and a name is level with the first line of its value. An empty value still takes one line. Below 48rem the columns fold into one: a name sits on its value, and pad-sm lies above the next name. The actions are md under the values, at the right, with a button&#39;s height. Selected is the raise surface and a blue line of two at the left.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/tcard/" title="Tcard" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/tcard/" target="_blank" rel="noopener">Tcard</a></figcaption></figure>',11)])])}const f=t(r,[["render",c]]);export{m as __pageData,f as default};
